1	/**
2	 * Real-kernel verification of the cgroup resource limits on evaluator commands (v1.1.4 WP-1105 / audit A9).
3	 *
4	 * Every check launches a command through the production evaluator-command runner (`createContainedRunner`, the code
5	 * behind `runArgv` that build and typecheck_clean use) with `resources` set small, and reads the kernel's own
6	 * counters. Nothing here is an injected runner: the only injected seam is a pass-through spy that keeps the
7	 * supervisor's report, which the runner otherwise reduces to status/signal/error.
8	 *
9	 * Skipped, with the reason printed, unless this host can run the contract for real: cgroup v2 with a systemd user
10	 * manager that delegates cpu+memory+pids, Bubblewrap, prlimit, and a dedicated tmpfs in
11	 * NEXUS_EVAL_TEST_WORKSPACE_ROOT (the same fixture `make test-ci` and CI provide). A skip is not verification.
12	 *
13	 * Safety: the supervisor applies and reads back memory.max, pids.max and cpu.max on the payload cgroup BEFORE the
14	 * command starts, and refuses (never runs the command) when it cannot. The hog, the fork bomb and the busy loops only
15	 * ever run inside that cgroup, with a wall-clock timeout.
16	 */
17	import { test } from "node:test";
18	import type { TestContext } from "node:test";
19	import assert from "node:assert/strict";
20	import fs from "node:fs";
21	import os from "node:os";
22	import path from "node:path";
23	import { randomUUID } from "node:crypto";
24	import { spawnSync } from "node:child_process";
25	import { fileURLToPath } from "node:url";
26	
27	const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
28	const MIB = 1024 * 1024;
29	const uid = process.getuid!();
30	const USER_SERVICE = `/sys/fs/cgroup/user.slice/user-${uid}.slice/user@${uid}.service`;
31	/**
32	 * Where transient scopes land on this host: the parent of the cgroup a real `systemd-run --user --scope` command reports in
33	 * /proc/self/cgroup, discovered by the gate (never assumed). Unset until the gate has run; a use before then throws.
34	 */
35	let SCOPE_PARENT: string | null = null;
36	const scopeParent = () => { if (!SCOPE_PARENT) throw new Error("the host gate has not discovered the scope directory"); return SCOPE_PARENT; };
37	
38	/** The directory transient scopes are created in, or why it cannot be found. Needs a working user manager. */
39	function discoverScopeParent(): { dir: string } | { problem: string } {
40	  const probe = spawnSync("/usr/bin/systemd-run", ["--user", "--scope", "--quiet", "--collect", "--", "/bin/cat", "/proc/self/cgroup"], {
41	    encoding: "utf8", timeout: 15_000, env: { PATH: "/usr/bin:/bin", XDG_RUNTIME_DIR: process.env.XDG_RUNTIME_DIR, ...(process.env.DBUS_SESSION_BUS_ADDRESS ? { DBUS_SESSION_BUS_ADDRESS: process.env.DBUS_SESSION_BUS_ADDRESS } : {}) },
42	  });
43	  const own = (probe.stdout ?? "").split("\n").find((line) => line.startsWith("0::"))?.slice(3);
44	  if (probe.status !== 0 || !own || !own.endsWith(".scope")) return { problem: `a probe scope did not report a transient scope cgroup (exit ${probe.status}: ${(probe.stderr ?? "").trim().slice(-200)}; cgroup "${own ?? ""}")` };
45	  const dir = path.dirname(path.join("/sys/fs/cgroup", own));
46	  if (!fs.existsSync(path.join(dir, "cgroup.procs"))) return { problem: `transient scopes are not created under ${dir}: it is not a cgroup directory here` };
47	  return { dir };
48	}
49	
50	/** memory.peak (kernel 5.19) and pids.peak (6.1) may be absent: the peak bounds are then reported as not checked, not failed. */
51	const PEAKS = fs.existsSync(path.join(USER_SERVICE, "memory.peak")) && fs.existsSync(path.join(USER_SERVICE, "pids.peak"));
52	
53	type Final = Record<string, any>;
54	type Run = { result: any; final: Final | undefined; sampled: Sampled; marker: string; ms: number; before: Set<string> };
55	type Sampled = { scopes: string[]; raw: Record<string, string> };
56	
57	const read = (file: string) => { try { return fs.readFileSync(file, "utf8"); } catch { return null; } };
58	const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
59	
60	/** Why this host cannot verify the contract for real, or null. Computed once; the probe is a harmless `true` in a scope. */
61	let gate: Promise<{ reason: string | null; resources?: any }> | undefined;
62	function hostGate() {
63	  gate ??= (async () => {
64	    if (process.platform !== "linux") return { reason: "not Linux" };
65	    if (!fs.existsSync("/sys/fs/cgroup/cgroup.controllers")) return { reason: "no cgroup v2 unified hierarchy at /sys/fs/cgroup" };
66	    if (!fs.existsSync(path.join(USER_SERVICE, "cgroup.kill"))) return { reason: "this kernel has no cgroup.kill (before 5.14): the harness could not stop a fork bomb" };
67	    const delegated = read(path.join(USER_SERVICE, "cgroup.controllers"))?.trim().split(/\s+/) ?? [];
68	    for (const controller of ["cpu", "memory", "pids"]) {
69	      if (!delegated.includes(controller)) return { reason: `the systemd user manager does not delegate the ${controller} controller (${USER_SERVICE}/cgroup.controllers: "${delegated.join(" ")}")` };
70	    }
71	    if (!fs.existsSync("/usr/bin/pgrep")) return { reason: "pgrep is unavailable" };
72	    if (!process.env.XDG_RUNTIME_DIR) return { reason: "XDG_RUNTIME_DIR is unset: no systemd user manager session" };
73	    const workspaceRoot = process.env.NEXUS_EVAL_TEST_WORKSPACE_ROOT;
74	    if (!workspaceRoot) return { reason: "NEXUS_EVAL_TEST_WORKSPACE_ROOT is unset: no dedicated capped tmpfs for the resource contract (run `make test-ci`)" };
75	    const { resourceProbeProblem } = await import(path.join(ROOT, "eval/resources.mjs"));
76	    const { sandboxAvailable } = await import(path.join(ROOT, "eval/isolate.mjs"));
77	    if (!sandboxAvailable()) return { reason: "Bubblewrap is unavailable or cannot start here" };
78	    if (!fs.existsSync("/usr/bin/prlimit")) return { reason: "prlimit is unavailable" };
79	    const tmpfs = fs.statfsSync(workspaceRoot);
80	    const resources = { cpuPercent: 50, memoryBytes: 64 * MIB, tasks: 16, storageBytes: tmpfs.blocks * tmpfs.bsize, workspaceRoot };
81	    const problem = resourceProbeProblem(resources);
82	    if (problem) return { reason: `the resource contract probe fails on this host: ${problem}` };
83	    const discovered = discoverScopeParent();
84	    if ("problem" in discovered) return { reason: discovered.problem };
85	    SCOPE_PARENT = discovered.dir;
86	    return { reason: null, resources };
87	  })();
88	  return gate;
89	}
90	
91	/** The resources to use. Without the fixtures: skip with the reason and return null. With them set (CI, `make test-ci`): fail, as eval_integrity does, so a lost delegation cannot turn this file green by skipping. */
92	async function requireHost(t: TestContext) {
93	  const { reason, resources } = await hostGate();
94	  if (reason && process.env.NEXUS_EVAL_TEST_WORKSPACE_ROOT) assert.fail(`the CI evaluator fixtures are configured (NEXUS_EVAL_TEST_WORKSPACE_ROOT is set) but the cgroup contract cannot run: ${reason}`);
95	  if (reason) { t.skip(`cannot verify cgroup limits on this host: ${reason}`); return null; }
96	  return resources;
97	}
98	
99	/** The scope directory's entries. It may be gone when no scope exists (systemd removes an empty slice): then none. Any other error is a failure, never an empty listing. */
100	function readScopeDir(): string[] {
101	  try { return fs.readdirSync(scopeParent()); }
102	  catch (error: any) { if (error?.code === "ENOENT") return []; throw error; }
103	}
104	
105	/** Scope cgroups (under the user manager) whose payload leaf holds a process whose command line contains `marker`. */
106	function scopesHolding(marker: string) {
107	  const found: string[] = [];
108	  let entries: string[] = [];
109	  entries = readScopeDir();
110	  for (const entry of entries) {
111	    if (!entry.startsWith("run-") || !entry.endsWith(".scope")) continue;
112	    const procs = read(path.join(scopeParent(), entry, "payload", "cgroup.procs"));
113	    if (!procs) continue;
114	    for (const pid of procs.split("\n").filter(Boolean)) {
115	      if ((read(`/proc/${pid}/cmdline`) ?? "").includes(marker)) { found.push(path.join(scopeParent(), entry)); break; }
116	    }
117	  }
118	  return found;
119	}
120	
121	/** Names of the transient scopes under the user manager right now (the directory may not exist: then none). */
122	function listScopes(): Set<string> {
123	  return new Set(readScopeDir().filter((e) => e.startsWith("run-") && e.endsWith(".scope")));
124	}
125	
126	/** Poll the cgroup files of this run's scope while it lives, as raw evidence next to the supervisor's report (informational: a short run can end between ticks). */
127	function startSampler(marker: string): { stop: () => Sampled } {
128	  const scopes = new Set<string>();
129	  const raw: Record<string, string> = {};
130	  const timer = setInterval(() => {
131	    for (const scope of scopesHolding(marker)) {
132	      scopes.add(scope);
133	      for (const file of ["memory.events", "pids.events", "cpu.stat", "memory.max", "pids.max", "cpu.max", "memory.swap.max", "memory.oom.group"]) {
134	        const text = read(path.join(scope, "payload", file));
135	        if (text !== null) raw[file] = text.trim();
136	      }
137	    }
138	  }, 15);
139	  return { stop: () => { clearInterval(timer); return { scopes: [...scopes], raw }; } };
140	}
141	
142	async function launch(resources: any, command: string, args: string[], timeoutMs: number, opts: { env?: Record<string, string | undefined>; cwd?: string } = {}): Promise<Run> {
143	  const { createContainedRunner } = await import(path.join(ROOT, "eval/evaluators/code/command.mjs"));
144	  const { runIsolatedProcess } = await import(path.join(ROOT, "eval/isolate.mjs"));
145	  let final: Final | undefined;
146	  const runner = createContainedRunner({
147	    runIsolatedProcess: async (spec: any, options: any) => { const outcome = await runIsolatedProcess(spec, options); final = outcome.resources; return outcome; },
148	  });
149	  const marker = `nexus-a9-${randomUUID()}`;
150	  const cwd = opts.cwd ?? fs.mkdtempSync(path.join(resources.workspaceRoot, "a9-cgroup-"));
151	  const saved: Record<string, string | undefined> = {};
152	  for (const [key, value] of Object.entries(opts.env ?? {})) { saved[key] = process.env[key]; if (value === undefined) delete process.env[key]; else process.env[key] = value; }
153	  const before = listScopes();
154	  const sampler = startSampler(marker);
155	  const started = Date.now();
156	  try {
157	    const result = await runner(command, [...args, marker], { cwd, timeoutMs, resources });
158	    const ms = Date.now() - started;
159	    return { result, final, sampled: sampler.stop(), marker, ms, before };
160	  } finally {
161	    sampler.stop();
162	    for (const [key, value] of Object.entries(saved)) { if (value === undefined) delete process.env[key]; else process.env[key] = value; }
163	    if (!opts.cwd) fs.rmSync(cwd, { recursive: true, force: true });
164	  }
165	}
166	
167	/** The shell script runs as `sh -c <script> <marker>`: `$0` carries the marker into every process's argv. */
168	const sh = (resources: any, script: string, timeoutMs: number, opts = {}) => launch(resources, "/bin/sh", ["-c", script], timeoutMs, opts);
169	
170	/**
171	 * Nothing of this run is left: every scope that appeared since the run started is gone, or is some other run's live scope
172	 * (populated by processes that do not carry this run's marker). An unpopulated new scope, or one still holding this
173	 * run's marker, is a leftover. Scopes the sampler saw must also be gone. No process carrying the marker survives.
174	 */
175	async function assertCleanedUp(run: Run, { mustHaveSeenScope = true } = {}) {
176	  // Runs that live for 1 s or more cannot slip between 15 ms sampler ticks; without this the scope-directory check could be vacuous.
177	  if (mustHaveSeenScope) assert.ok(run.sampled.scopes.length >= 1, "the sampler never saw this run's scope, so the scope-directory cleanup check would be vacuous");
178	  const leftovers = () => {
179	    const out: string[] = [];
180	    for (const name of listScopes()) {
181	      if (run.before.has(name)) continue;
182	      const dir = path.join(scopeParent(), name);
183	      const populated = !/^populated 0$/m.test(read(path.join(dir, "cgroup.events")) ?? "populated 0");
184	      if (!populated || scopesHolding(run.marker).includes(dir)) out.push(dir);
185	    }
186	    for (const dir of run.sampled.scopes) if (fs.existsSync(dir) && !out.includes(dir)) out.push(dir);
187	    return out;
188	  };
189	  const deadline = Date.now() + 8000;
190	  let leftover = leftovers();
191	  while (leftover.length && Date.now() < deadline) { await sleep(100); leftover = leftovers(); }
192	  for (const scope of leftover) { try { fs.writeFileSync(path.join(scope, "cgroup.kill"), "1"); } catch {} }
193	  assert.deepEqual(leftover, [], "a transient scope cgroup outlived its command");
194	  const pgrep = spawnSync("/usr/bin/pgrep", ["-f", run.marker], { encoding: "utf8" });
195	  assert.equal(pgrep.status, 1, `a process carrying the run marker survived: ${pgrep.stdout}`);
196	  assert.equal(run.final?.cleaned, true, JSON.stringify(run.final));
197	}
198	
199	/** A peak bound (memory.peak, pids.peak) when the kernel exposes it; otherwise print that it was not checked. */
200	function assertPeak(t: TestContext, final: Final, key: "memoryPeakBytes" | "pidsPeak", limit: number) {
201	  if (!PEAKS) { t.diagnostic(`${key} bound NOT checked: this kernel does not expose memory.peak/pids.peak`); return; }
202	  assert.equal(typeof final[key], "number", `${key} was not reported`);
203	  assert.ok(final[key] <= limit, `${key} ${final[key]} exceeded ${limit}`);
204	}
205	
206	function reportOf(run: Run): Final {
207	  assert.ok(run.final, `the resource supervisor produced no final report: ${JSON.stringify(run.result)}`);
208	  return run.final;
209	}
210	
211	function note(t: TestContext, label: string, run: Run) {
212	  t.diagnostic(`${label} ms=${run.ms} result=${JSON.stringify({ ...run.result, stdout: run.result.stdout.slice(0, 200), stderr: run.result.stderr.slice(0, 300) })}`);
213	  t.diagnostic(`${label} supervisor-report=${JSON.stringify(run.final)}`);
214	  for (const [file, text] of Object.entries(run.sampled.raw)) t.diagnostic(`${label} raw ${file}=${JSON.stringify(text)}`);
215	}
216	
217	test("the host fixtures for the cgroup limit checks are reported (a skip below is not verification)", async (t) => {
218	  const { reason } = await hostGate();
219	  t.diagnostic(reason ? `SKIPPED: ${reason}` : `kernel ${os.release()} cgroup2 user delegation present; checks run for real`);
220	});
221	
222	test("a memory hog is OOM-killed inside its cgroup, reported as a memory-limit kill, and never exceeds its limit", { timeout: 60_000 }, async (t) => {
223	  const resources = await requireHost(t);
224	  if (!resources) return;
225	  // `tail` of an endless line without a newline buffers all of it: unbounded anonymous memory.
226	  const run = await launch(resources, "/usr/bin/tail", ["/dev/zero"], 30_000);
227	  note(t, "memory", run);
228	  const final = reportOf(run);
229	  assert.equal(final.limits["memory.max"], String(resources.memoryBytes), "the 64 MiB limit was read back from the kernel before the command ran");
230	  assert.equal(final.limits["memory.swap.max"], "0");
231	  assert.ok(final.oomKills >= 1, `memory.events oom_kill: ${JSON.stringify(final)}`);
232	  assert.ok(final.memoryMaxEvents >= 1);
233	  assertPeak(t, final, "memoryPeakBytes", resources.memoryBytes);
234	  assert.notEqual(run.result.status, 0);
235	  assert.equal(run.result.timedOut, false, "it died of the limit, not the wall clock");
236	  assert.match(run.result.error ?? "", /memory limit/, "the operator is told a limit was hit");
237	  await assertCleanedUp(run);
238	});
239	
240	test("a shell that forks past pids.max gets EAGAIN and the supervisor records it", { timeout: 60_000 }, async (t) => {
241	  const resources = await requireHost(t);
242	  if (!resources) return;
243	  const run = await sh(resources, "for i in $(seq 40); do sleep 3 & done; wait", 20_000);
244	  note(t, "pids-loop", run);
245	  const final = reportOf(run);
246	  assert.equal(final.limits["pids.max"], String(resources.tasks));
247	  assert.ok(final.pidsMaxEvents >= 1, `pids.events max: ${JSON.stringify(final)}`);
248	  assertPeak(t, final, "pidsPeak", resources.tasks);
249	  assert.match(run.result.stderr, /Cannot fork|Resource temporarily unavailable|EAGAIN/i, "the shell's own fork failed with EAGAIN");
250	  await assertCleanedUp(run);
251	});
252	
253	test("a real fork bomb is bounded by pids.max and killed with its cgroup; fork keeps working outside it", { timeout: 60_000 }, async (t) => {
254	  const resources = await requireHost(t);
255	  if (!resources) return;
256	  // The classic bomb in a respawn loop, silenced (its error spam would hit the output cap), stopped by the wall clock (or, if the group OOM kill comes first, by that), never outside the cgroup.
257	  // bash survives a failed fork (dash exits on the first one), so the loop keeps bombing until the clock stops it.
258	  const bomb = "b() { b | b & }; while :; do b 2>/dev/null; done";
259	  const during: number[] = [];
260	  const probe = setInterval(() => { during.push(spawnSync("/usr/bin/true").status ?? -1); }, 250);
261	  let run: Run;
262	  try { run = await launch(resources, "/usr/bin/bash", ["-c", bomb], 4000); } finally { clearInterval(probe); }
263	  note(t, "fork-bomb", run);
264	  const final = reportOf(run);
265	  assert.ok(run.result.timedOut === true || final.oomKills > 0, "the bomb ends by the wall clock (or a group OOM kill)");
266	  assert.ok(final.pidsMaxEvents >= 5, `pids.events max=${final.pidsMaxEvents}`);
267	  assertPeak(t, final, "pidsPeak", resources.tasks);
268	  const forked = during.filter((status) => status === 0).length;
269	  t.diagnostic(`fork-bomb host-side /usr/bin/true probes every 250 ms during the run (exit statuses)=${JSON.stringify(during)}`);
270	  assert.ok(during.length >= 1 && forked === during.length, `the host could not fork while the bomb ran: ${JSON.stringify(during)}`);
271	  await assertCleanedUp(run);
272	});
273	
274	for (const [cpuPercent, loops] of [[20, 2], [50, 3]] as const) {
275	  test(`a CPU burner is throttled to cpu.max at ${cpuPercent}% (${loops} busy loops for 2 s)`, { timeout: 60_000 }, async (t) => {
276	    const base = await requireHost(t);
277	    if (!base) return;
278	    const resources = { ...base, cpuPercent };
279	    const busy = Array.from({ length: loops }, () => "timeout 2 sh -c 'while :; do :; done' &").join(" ");
280	    const run = await sh(resources, `${busy} wait`, 20_000);
281	    note(t, `cpu-${cpuPercent}`, run);
282	    const final = reportOf(run);
283	    const quotaUsec = (cpuPercent / 100) * 2_000_000;
284	    t.diagnostic(`cpu-${cpuPercent} usage_usec=${final.cpuUsageUsec} throttled_usec=${final.cpuThrottledUsec} quota_over_2s_usec=${quotaUsec} unthrottled_demand_usec=${loops * 2_000_000}`);
285	    assert.equal(final.limits["cpu.max"], `${cpuPercent * 1000} 100000`);
286	    assert.ok(final.cpuThrottledUsec > 0, "cpu.stat throttled_usec must be > 0");
287	    // Demand is `loops` full cores; the quota is a fraction of one. Bound usage by the measured wall time of the whole run
288	    // (start-up and kill latency included) at the quota, plus 10% and one 100 ms period of burst.
289	    const allowed = (cpuPercent / 100) * run.ms * 1000 * 1.1 + 100_000;
290	    assert.ok(final.cpuUsageUsec <= allowed, `used ${final.cpuUsageUsec} us, quota over ${run.ms} ms allows ${allowed}`);
291	    assert.ok(final.cpuUsageUsec > 0);
292	    assert.equal(run.result.error, null);
293	    await assertCleanedUp(run);
294	  });
295	}
296	
297	test("a clean command under the same limits succeeds untouched (the limits do not break ordinary work)", { timeout: 60_000 }, async (t) => {
298	  const resources = await requireHost(t);
299	  if (!resources) return;
300	  const cwd = fs.mkdtempSync(path.join(resources.workspaceRoot, "a9-cgroup-"));
301	  let run: Run;
